export function formatValue(value: number, unit: KPIData['unit']): string {
  switch (unit) {
    case 'currency':
      return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 0,
        notation: value >= 1000000 ? 'compact' : 'standard',
      }).format(value);
    case 'currency-per-unit':
      return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 0,
      }).format(value);
    case 'number':
    default:
      return new Intl.NumberFormat('en-IN').format(value);
  }
}

export function formatChangePct(changePct: number): string {
  const sign = changePct >= 0 ? '↑' : '↓';
  return `${sign} ${Math.abs(changePct).toFixed(1)}%`;
}

export function getTrendDirection(changePct: number): TrendDirection {
  if (changePct > 0.5) return 'up';
  if (changePct < -0.5) return 'down';
  return 'neutral';
}