'use client';

import Link from 'next/link';

interface InvestigateButtonProps {
  metricId: string;
  severity: 'normal' | 'high' | 'critical';
  anomaly?: boolean;
  className?: string;
}

export function InvestigateButton({ metricId, severity, anomaly = false, className = '' }: InvestigateButtonProps) {
  if (!anomaly && severity === 'normal') {
    return null;
  }

  const isHighSeverity = severity === 'high' || severity === 'critical';

  return (
    <Link
      href={`/investigate/${metricId}`}
      className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 ${
        isHighSeverity
          ? 'bg-red-600 text-white hover:bg-red-700 focus:ring-red-500'
          : 'bg-slate-100 text-slate-700 hover:bg-slate-200 focus:ring-slate-400 dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700'
      } ${className}`}
    >
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
      </svg>
      Investigate
    </Link>
  );
}